(* ^safe-r5ye ^safe-r5ye: genuine installed leased API, owner callbacks remain Eio. *)
module B = Ox_blocking
let native ~pool () = Eio_main.run (fun _ -> ignore (B.run_leased_result ~pool ~release:(fun _ -> ()) (fun () -> Unix.sleepf 0.001; Ok ())))
let release_wait ~pool () = Eio_main.run (fun _ -> ignore (B.run_leased_result ~pool ~release:(fun _ -> Thread.delay 0.001) (fun () -> Ok ())))
let cancel_wait ~pool () = Eio_main.run (fun _ -> ignore (B.run_leased_result ~pool ~on_cancel:(fun () -> Unix.sleep 0) ~release:(fun _ -> ()) (fun () -> Ok ())))
let computed_release ~pool () = Eio_main.run (fun _ -> ignore (B.run_leased_result ~pool ~release:(Unix.sleepf 0.001; fun _ -> ()) (fun () -> Ok ())))
let opaque_release ~pool release () = Eio_main.run (fun _ -> ignore (B.run_leased_result ~pool ~release (fun () -> Ok ())))
let missing_release ~pool () = Eio_main.run (fun _ -> let _partial = B.run_leased_result ~pool ~on_cancel:(fun () -> Thread.delay 0.001) (fun () -> Ok ()) in ())
let missing_pool () = Eio_main.run (fun _ -> let _partial = B.run_leased_result ~release:(fun _ -> Unix.sleepf 0.001) (fun () -> Ok ()) in ())
let native_alias ~pool () = let lease = B.run_leased_result in Eio_main.run (fun _ -> ignore (lease ~pool ~release:(fun _ -> ()) (fun () -> Unix.sleep 0; Thread.delay 0.001; Ok ())))
let counting_native ~pool semaphore () = Eio_main.run (fun _ -> ignore (B.run_leased_result ~pool ~release:(fun _ -> ()) (fun () -> Semaphore.Counting.acquire semaphore; Ok ())))
let counting_owner semaphore () = Eio_main.run (fun _ -> Semaphore.Counting.acquire semaphore)
let counting_release ~pool semaphore () = Eio_main.run (fun _ -> ignore (B.run_leased_result ~pool ~release:(fun _ -> Semaphore.Counting.acquire semaphore) (fun () -> Ok ())))
